INSERT INTO package_questions (package_id, question_json, hash_logico, order_index, status) VALUES ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"A ''órbita'' abriga o globo ocular e seus anexos. Qual destes ossos NÃO faz parte da parede da órbita?","options":{"a":"Osso Frontal.","b":"Osso Esfenoide.","c":"Osso Zigomático.","d":"Osso Temporal.","e":"Osso Etmoide."},"answer":"d","rationale":"As paredes da órbita são formadas pelos ossos frontal, esfenoide, zigomático, maxila, etmoide, lacrimal e palatino. O temporal não contribui para a órbita.","option_rationales":{"a":"Errada.","b":"Errada.","c":"Errada.","d":"Correta. Osteologia do crânio.","e":"Errada."},"difficulty":"Média","tags":["Anatomia","Cabeça e Pescoço","Osteologia/Órbita"]}', '639d180a147adf1961a29f0648c9b408', 475, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"Qual o principal músculo responsável pela ELEVAÇÃO da pálpebra superior e qual o seu nervo motor?","options":{"a":"Músculo orbicular do olho; Nervo Facial.","b":"Músculo levantador da pálpebra superior; Nervo Oculomotor (III).","c":"Músculo levantador da pálpebra superior; Nervo Trigêmeo.","d":"Músculo reto superior; Nervo Oculomotor.","e":"Músculo tarsal superior; Nervos simpáticos apenas."},"answer":"b","rationale":"O levantador da pálpebra superior é o motor principal (N. III). O orbicular do olho (N. VII) fecha a pálpebra.","option_rationales":{"a":"Errada. Fecha a pálpebra.","b":"Correta. Miologia da órbita.","c":"Errada.","d":"Errada. Move o globo ocular para cima.","e":"Errada. Auxilia, mas não é o motor voluntário principal."},"difficulty":"Fácil","tags":["Anatomia","Cabeça e Pescoço","Miologia/Órbita"]}', '8b73d17a3ec8d368129a0c8922577898', 476, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O ''músculo oblíquo superior'' do olho realiza rotação interna e depressão. Qual nervo craniano o inerva exclusivamente?","options":{"a":"Oculomotor (III).","b":"Troclear (IV).","c":"Abducente (VI).","d":"Oftálmico (V1).","e":"Óptico (II)."},"answer":"b","rationale":"Mnemônico: SO4 (Superior Oblique - IV) e LR6 (Lateral Rectus - VI). O restante é III.","option_rationales":{"a":"Errada.","b":"Correta. Neuroanatomia motora ocular.","c":"Errada. Inerva o reto lateral.","d":"Errada.","e":"Errada. É sensitivo especial."},"difficulty":"Fácil","tags":["Anatomia","Cabeça e Pescoço","Neuroanatomia/Órbita"]}', 'fb879e88cca8702bc0e5464a9ca33060', 477, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"A ''faringe'' é dividida em três partes. Em qual delas se localiza a abertura da ''tuba auditiva'' (de Eustáquio)?","options":{"a":"Nasofaringe.","b":"Orofaringe.","c":"Laringofaringe.","d":"Esôfago superior.","e":"Ádito da laringe."},"answer":"a","rationale":"A tuba auditiva conecta a orelha média à nasofaringe para equilibrar pressões.","option_rationales":{"a":"Correta. Esplanccnologia da faringe.","b":"Errada.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Fácil","tags":["Anatomia","Cabeça e Pescoço","Esplanccnologia"]}', '339b633d1bf53fd7471113aaafd817d7', 478, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O ''anel linfático de Waldeyer'' é um conjunto de tecidos linfoides na garganta. Qual ''amígdala'' (tonsila) se localiza no teto da nasofaringe e, quando aumentada, é chamada de ''adenoides''?","options":{"a":"Tonsila Palatina.","b":"Tonsila Faríngea.","c":"Tonsila Lingual.","d":"Tonsila Tubária.","e":"Linfonodo de Virchow."},"answer":"b","rationale":"A tonsila faríngea situa-se na mucosa do teto e parede posterior da nasofaringe.","option_rationales":{"a":"Errada. Fica na orofaringe (amígdala clássica).","b":"Correta. Sistema linfático cervical.","c":"Errada. Base da língua.","d":"Errada.","e":"Errada."},"difficulty":"Fácil","tags":["Anatomia","Cabeça e Pescoço","Esplanccnologia"]}', '7a31aa8cbb467ede3799fbe338df0c33', 479, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O ''músculo estapédio'', localizado na orelha média, protege o ouvido contra sons excessivamente altos. Qual nervo craniano o inerva?","options":{"a":"Nervo Trigêmeo.","b":"Nervo Facial (VII).","c":"Nervo Vestibulococlear (VIII).","d":"Nervo Glossofaríngeo.","e":"Nervo Vago."},"answer":"b","rationale":"O nervo para o estapédio é um ramo do nervo facial. O músculo tensor do tímpano é inervado pelo trigêmeo (V).","option_rationales":{"a":"Errada. Inerva o tensor do tímpano.","b":"Correta. Anatomia da orelha.","c":"Errada. Transporta o estímulo sonoro e de equilíbrio.","d":"Errada.","e":"Errada."},"difficulty":"Difícil","tags":["Anatomia","Cabeça e Pescoço","Órgãos do Sentido/Neuro"]}', '5cce354fd61c84ea60a155ce205b7993', 480, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"A ''orelha média'' comunica-se com as ''células mastóideas'' através de qual abertura?","options":{"a":"Janela oval.","b":"Ádito para o antro mastoideo.","c":"Janela redonda.","d":"Tuba auditiva.","e":"Meato acústico externo."},"answer":"b","rationale":"Infecções do ouvido médio podem se espalhar para o processo mastoide através deste ádito.","option_rationales":{"a":"Errada. Comunica-se com o vestíbulo.","b":"Correta. Topografia do osso temporal.","c":"Errada.","d":"Errada. Comunica-se com a faringe.","e":"Errada."},"difficulty":"Difícil","tags":["Anatomia","Cabeça e Pescoço","Órgãos do Sentido"]}', '44559fc8df103e79734ce803a0afe3a6', 481, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"Qual estrutura anatômica da ''orelha interna'' é responsável pela DETECÇÃO DA ACELERAÇÃO LINEAR (como a gravidade)?","options":{"a":"Canais semicirculares.","b":"Cóclea.","c":"Utrículo e Sáculo (máculas).","d":"Órgão de Corti.","e":"Membrana timpânica."},"answer":"c","rationale":"O utrículo e sáculo detectam aceleração linear. Os canais semicirculares detectam aceleração angular (rotação).","option_rationales":{"a":"Errada.","b":"Errada. Audição.","c":"Correta. Fisiologia aplicada da orelha interna.","d":"Errada. Audição.","e":"Errada."},"difficulty":"Média","tags":["Anatomia","Cabeça e Pescoço","Órgãos do Sentido"]}', 'f8f79e346fbeddd5c90c5689e97a69bd', 482, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O ''couro cabeludo'' possui cinco camadas (S-C-A-L-P). Qual camada é considerada o ''espaço perigoso'' por permitir a disseminação livre de infecções e sangue?","options":{"a":"Skin (Pele).","b":"Connective tissue (Tecido conjuntivo denso).","c":"Aponeurose epicraniana.","d":"Loose connective tissue (Tecido conjuntivo frouxo).","e":"Pericrânio (periósteo)."},"answer":"d","rationale":"A 4ª camada (tecido frouxo) permite que fluidos se desloquem facilmente e infecções alcancem as veias emissárias.","option_rationales":{"a":"Errada.","b":"Errada.","c":"Errada.","d":"Correta. Anatomia de superfície e clínica.","e":"Errada. Está fixo ao osso."},"difficulty":"Média","tags":["Anatomia","Cabeça e Pescoço","Topografia/Clínica"]}', '17a7b341f496ad7bfd68938fc097be9b', 483, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"A ''glândula submandibular'' tem seu ducto de drenagem abrindo em qual local da cavidade oral?","options":{"a":"No vestíbulo da boca, oposto ao 2º molar superior (Ducto de Stenon).","b":"Na carúncula sublingual, na base do freio da língua.","c":"Diretamente nas tonsilas palatinas.","d":"No palato duro.","e":"Na bochecha."},"answer":"b","rationale":"O ducto submandibular (de Wharton) abre-se na carúncula sublingual.","option_rationales":{"a":"Errada. Drenagem da parótida.","b":"Correta. Esplanccnologia oral.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Média","tags":["Anatomia","Cabeça e Pescoço","Esplanccnologia"]}', '20c91e467b9f1b7d1596db93ef6817da', 484, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O ''nervo glossofaríngeo'' (IX) é responsável pela inervação de qual músculo do pescoço (o único que ele inerva motoramente)?","options":{"a":"Estilofaringeo.","b":"Salpingofaríngeo.","c":"Constritor superior da faringe.","d":"Cricotireoideo.","e":"Digástrico."},"answer":"a","rationale":"O estilofaríngeo deriva do 3º arco branquial, cujo nervo é o glossofaríngeo.","option_rationales":{"a":"Correta. Neuroanatomia motora faríngea.","b":"Errada. Inervado pelo Vago.","c":"Errada. Inervado pelo Vago.","d":"Errada. Inervado pela laringe superior (Vago).","e":"Errada."},"difficulty":"Difícil","tags":["Anatomia","Cabeça e Pescoço","Neuroanatomia/Miologia"]}', '639177c589b391376e4a0ab8508e5bdf', 485, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"Em uma ''punção de veia jugular interna'', qual a relação anatômica mais importante dessa veia com a artéria carótida comum dentro da bainha carotídea?","options":{"a":"A veia está medial à artéria.","b":"A veia está lateral à artéria.","c":"A veia está posterior à artéria.","d":"A veia está profunda ao esôfago.","e":"As duas estão em compartimentos diferentes."},"answer":"b","rationale":"A jugular interna situa-se lateralmente à carótida comum. O nervo vago situa-se posteriormente entre as duas.","option_rationales":{"a":"Errada. Risco de punção arterial acidental.","b":"Correta. Anatomia aplicada/Procedimentos.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Difícil","tags":["Anatomia","Cabeça e Pescoço","Topografia/Angiologia"]}', 'cb374fccbf289bdb8de7595821f433d5', 486, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"A ''fenda glótica'' (rima da glote) é o espaço entre quais estruturas na laringe?","options":{"a":"Pregas vestibulares (cordas vocais falsas).","b":"Pregas vocais verdadeiras.","c":"Epiglote e cartilagem tireoide.","d":"Cartilagens aritenoides apenas.","e":"Traqueia e laringe."},"answer":"b","rationale":"A rima da glote é a abertura entre as pregas vocais, sendo o local mais estreito da via aérea no adulto.","option_rationales":{"a":"Errada. Esse espaço é a rima do vestíbulo.","b":"Correta. Esplanccnologia respiratória.","c":"Errada.","d":"Errada. Estas delimitam a parte posterior da rima.","e":"Errada."},"difficulty":"Fácil","tags":["Anatomia","Cabeça e Pescoço","Esplanccnologia"]}', '7a4f17109ef7588cc70b236adaba40fa', 487, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"Qual o único músculo da laringe responsável pela ABDUÇÃO (abertura) das pregas vocais, essencial para a respiração?","options":{"a":"Cricoaritenoide lateral.","b":"Cricoaritenoide posterior.","c":"Tireoaritenoide.","d":"Cricotireoideo.","e":"Aritenoide transverso."},"answer":"b","rationale":"O CAP (Cricoaritenoide Posterior) é o único abdutor; todos os outros fecham ou tensionam as cordas.","option_rationales":{"a":"Errada. É adutor.","b":"Correta. Fisiologia vocal/anatomia.","c":"Errada.","d":"Errada. Tensiona as cordas (muda o tom).","e":"Errada."},"difficulty":"Difícil","tags":["Anatomia","Cabeça e Pescoço","Miologia/Laringe"]}', '9b1ebafaa2da895c1fb0413383cca7fa', 488, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O ''plexo cervical'' fornece inervação sensitiva para a pele do pescoço. Qual destes nervos faz parte deste plexo e cruza o músculo esternocleidomastoideo?","options":{"a":"Nervo supraescapular.","b":"Nervo auricular magno.","c":"Nervo facial.","d":"Nervo frênico.","e":"Nervo hipoglosso."},"answer":"b","rationale":"O auricular magno, o occipital menor, o cervical transverso e os supraclaviculares são os quatro ramos sensitivos cutâneos do plexo cervical.","option_rationales":{"a":"Errada. Ramo do plexo braquial.","b":"Correta. Neuroanatomia sensitiva cervical.","c":"Errada. Nervo craniano.","d":"Errada. É motor para o diafragma.","e":"Errada. Nervo craniano."},"difficulty":"Média","tags":["Anatomia","Cabeça e Pescoço","Neuroanatomia"]}', '6811de1985064ce339bb32bc3a38580d', 489, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O ''ducto torácico'' desemboca no sistema venoso em qual localização anatômica?","options":{"a":"Veia cava superior.","b":"Ângulo venoso esquerdo (junção da jugular interna esquerda e subclávia esquerda).","c":"Átrio direito.","d":"Veia braquiocefálica direita.","e":"Veia porta."},"answer":"b","rationale":"O ducto torácico drena a linfa da maior parte do corpo no lado esquerdo do pescoço.","option_rationales":{"a":"Errada.","b":"Correta. Angiologia/Sistema Linfático.","c":"Errada.","d":"Errada. Local de drenagem do ducto linfático direito.","e":"Errada."},"difficulty":"Média","tags":["Anatomia","Cabeça e Pescoço","Angiologia"]}', 'b60833d09cc67650ee5e940ff0de5517', 490, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O ''istmo do fauces'' marca a transição entre a boca e a faringe. Quais estruturas formam os seus pilares?","options":{"a":"Pregas palatoglosso e palatofaríngeo.","b":"Base da língua e epiglote.","c":"Palato duro e mole.","d":"Dentes molares.","e":"Úvula apenas."},"answer":"a","rationale":"Entre estes dois arcos (anterior e posterior) localiza-se a tonsila palatina.","option_rationales":{"a":"Correta. Esplanccnologia oral/faríngea.","b":"Errada.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Fácil","tags":["Anatomia","Cabeça e Pescoço","Esplanccnologia"]}', '7cb7250631e30edb3c6e862df2e6761a', 491, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"A ''fontanela anterior'' (moleira) no recém-nascido situa-se entre quais ossos?","options":{"a":"Parietais e Occipital.","b":"Frontais (sutura metópica) e Parietais.","c":"Parietais e Temporais.","d":"Osso Esfenoide.","e":"Esfenoide e Parietal."},"answer":"b","rationale":"A fontanela anterior (bregmática) é a maior e fecha-se por volta dos 18 meses.","option_rationales":{"a":"Errada. Local da fontanela posterior (lambdoidea).","b":"Correta. Osteologia pediátrica.","c":"Errada.","d":"Errada.","e":"Errada. Local da fontanela esfenoidal."},"difficulty":"Fácil","tags":["Anatomia","Cabeça e Pescoço","Osteologia"]}', '2a8a4e6d55f16570b44d4b5ce10f1cf4', 492, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"Qual destas glândulas salivares é considerada PURAMENTE SEROSA no adulto?","options":{"a":"Glândula Parótida.","b":"Glândula Submandibular.","c":"Glândula Sublingual.","d":"Glândulas salivares menores do palato.","e":"Todas são mistas."},"answer":"a","rationale":"A parótida é serosa. A submandibular é predominantemente serosa, mas mista. A sublingual é predominantemente mucosa.","option_rationales":{"a":"Correta. Esplanccnologia/Histologia aplicada.","b":"Errada.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Média","tags":["Anatomia","Cabeça e Pescoço","Esplanccnologia"]}', 'dc1887ffa7540ed9d8cdd147da174f34', 493, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"A ''hipófise'' (glândula pituitária) é dividida em adenohipófise e neurohipófise. Qual destas partes tem origem embrionária no teto da boca (Bolsa de Rathke)?","options":{"a":"Neurohipófise.","b":"Adenohipófise.","c":"Hipotálamo.","d":"Infundíbulo.","e":"Epinefrina."},"answer":"b","rationale":"A adenohipófise deriva do ectoderma oral, enquanto a neurohipófise deriva do neuroectoderma do diencéfalo.","option_rationales":{"a":"Errada.","b":"Correta. Embriologia aplicada à neuroanatomia.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Difícil","tags":["Anatomia","Cabeça e Pescoço","Neuroanatomia/Embriologia"]}', 'be391e949bf25347f3545d6240b90205', 494, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O ''corpo caloso'' é a maior estrutura de substância branca do cérebro. Qual a sua função primordial?","options":{"a":"Controle motor fino.","b":"Processamento visual primário.","c":"Comunicação e integração entre os dois hemisférios cerebrais.","d":"Produção de líquido cefalorraquidiano.","e":"Regulação do sono."},"answer":"c","rationale":"É uma comissura inter-hemisférica composta por milhões de axônios.","option_rationales":{"a":"Errada.","b":"Errada.","c":"Correta. Neuroanatomia funcional.","d":"Errada. Função do plexo coroide.","e":"Errada. Função do hipotálamo/pineal."},"difficulty":"Fácil","tags":["Anatomia","Cabeça e Pescoço","Neuroanatomia"]}', '96d072dfff28fcf8c8882fda86d696e0', 495, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O ''liquor'' (líquido cefalorraquidiano) circula no espaço subaracnoideo. Onde ele é REABSORVIDO para o sistema venoso?","options":{"a":"Plexos coroide.","b":"Granulações aracnoideas (Vilosidades).","c":"Aqueduto cerebral.","d":"Forames de Luschka.","e":"Canal central da medula."},"answer":"b","rationale":"As granulações aracnoideas projetam-se nos seios durais, principalmente no seio sagital superior.","option_rationales":{"a":"Errada. Local de produção.","b":"Correta. Dinâmica do liquor.","c":"Errada. Local de passagem entre 3º e 4º ventrículo.","d":"Errada. Saída dos ventrículos.","e":"Errada."},"difficulty":"Média","tags":["Anatomia","Cabeça e Pescoço","Neuroanatomia"]}', '98821a8db84dfc1a203a8d777e8bb528', 496, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"Qual área do córtex cerebral é responsável pela MOTRICIDADE DA FALA (formulação da linguagem) e localiza-se no giro frontal inferior?","options":{"a":"Área de Wernicke.","b":"SULCO central.","c":"Área de Broca.","d":"Córtex visual primário.","e":"Giro pré-central."},"answer":"c","rationale":"Uma lesão na área de Broca causa afasia de expressão (o paciente entende, mas não fala fluentemente). Wernicke é compreensão.","option_rationales":{"a":"Errada. Responsável pela compreensão.","b":"Errada.","c":"Correta. Neuroanatomia funcional/Mapeamento cortical.","d":"Errada.","e":"Errada. Área motora primária geral."},"difficulty":"Fácil","tags":["Anatomia","Cabeça e Pescoço","Neuroanatomia"]}', 'f0d2d27b902f506ad6fd422ec3837ac9', 497, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O ''nervo óptico'' (II) cruza no quiasma óptico. Fibras de qual região da retina cruzam para o lado oposto?","options":{"a":"Retina temporal (fibras laterais).","b":"Retina nasal (fibras mediais).","c":"Toda a retina cruza.","d":"Nenhuma fibra cruza.","e":"Apenas as fibras da mácula."},"answer":"b","rationale":"As fibras da metade nasal (que veem o campo visual temporal) decussam no quiasma.","option_rationales":{"a":"Errada. Estas permanecem ipsilaterais.","b":"Correta. Neuroanatomia das vias visuais.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Difícil","tags":["Anatomia","Cabeça e Pescoço","Neuroanatomia/Órgãos do Sentido"]}', 'b31d439f9ae8b4505bd69baadb7be81b', 498, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"Qual estrutura anatômica divide o ''pescoço'' em triângulo anterior e posterior?","options":{"a":"Músculo Trapézio.","b":"Músculo Esternocleidomastoideo.","c":"Músculo Omo-hioide.","d":"Clavícula.","e":"Osso hioide."},"answer":"b","rationale":"O esternocleidomastoideo é o divisor clássico entre estas duas grandes regiões topográficas.","option_rationales":{"a":"Errada. Limite posterior do triângulo posterior.","b":"Correta. Topografia cervical.","c":"Errada.","d":"Errada. Limite inferior.","e":"Errada."},"difficulty":"Fácil","tags":["Anatomia","Cabeça e Pescoço","Topografia"]}', '1b0703354816689d08d41321fe37942c', 499, 'draft');